class Solution:
    def visiblePoints(self, points: List[List[int]], angle: int, location: List[int]) -> int:
        angles = []
        same = 0
        lx, ly = location
        for x, y in points:
            if x == lx and y == ly:
                same += 1
            else:
                angles.append(math.degrees(math.atan2(y - ly, x - lx)))
        n = len(angles)
        best = 0
        for i in range(n):
            cnt = 0
            for j in range(n):
                if (angles[j] - angles[i]) % 360 <= angle + 1e-9:
                    cnt += 1
            best = max(best, cnt)
        return best + same

