class Solution {
public:
    int visiblePoints(vector<vector<int>>& points, int angle, vector<int>& location) {
        vector<double> angles;
        int same = 0;
        for (auto& p : points) {
            if (p[0] == location[0] && p[1] == location[1]) { ++same; continue; }
            angles.push_back(atan2(p[1] - location[1], p[0] - location[0]) * 180.0 / M_PI);
        }
        int n = angles.size(), best = 0;
        for (int i = 0; i < n; ++i) {
            int cnt = 0;
            for (int j = 0; j < n; ++j) {
                double d = fmod(angles[j] - angles[i], 360.0);
                if (d < 0) d += 360.0;
                if (d <= angle + 1e-9) ++cnt;
            }
            best = max(best, cnt);
        }
        return best + same;
    }
};

