class Solution {
public:
    int visiblePoints(vector<vector<int>>& points, int angle, vector<int>& location) {
        vector<double> angles;
        int same = 0;
        for (auto& p : points) {
            if (p[0] == location[0] && p[1] == location[1]) { ++same; continue; }
            angles.push_back(atan2(p[1] - location[1], p[0] - location[0]) * 180.0 / M_PI);
        }
        sort(angles.begin(), angles.end());
        int n = angles.size();
        for (int i = 0; i < n; ++i) angles.push_back(angles[i] + 360.0);
        int best = 0, left = 0;
        for (int right = 0; right < 2 * n; ++right) {
            while (angles[right] - angles[left] > angle + 1e-9) ++left;
            best = max(best, right - left + 1);
        }
        return best + same;
    }
};

